"use client";
import { useState } from "react";
import { useParams } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "@/components/ui/select";
import { SlotPicker } from "@/components/SlotPicker";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Calendar } from "lucide-react";

// Mock doctor data (replace with real fetch logic)
const mockDoctor = {
  _id: "1",
  fullName: "Dr. Sujit Pawar",
  avatarUrl: "/default-avatar.png",
  specialization: "Cardiologist",
  experience: 12,
  rating: 4.7,
  languages: ["English", "Hindi"],
  address: "123 Heart Clinic, Mumbai" ,
  isOnline: true,
  bio: "Experienced cardiologist with a passion for preventive care and patient education. Published in multiple journals.",
  fee: 800,
  slots: [
    { datetime: "2024-06-10T10:00:00", available: true },
    { datetime: "2024-06-10T10:30:00", available: false },
    { datetime: "2024-06-10T11:00:00", available: true },
    { datetime: "2024-06-11T09:00:00", available: true },
    { datetime: "2024-06-11T09:30:00", available: true },
    { datetime: "2024-06-12T14:00:00", available: true },
  ],
};

const mockPatient = {
  name: "John Doe",
  email: "john@example.com",
};

export default function DoctorProfilePage() {
  const { id } = useParams();
  const doctor = mockDoctor; // Replace with fetch by id
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [consultType, setConsultType] = useState("video");
  const [duration, setDuration] = useState("15");
  const [notes, setNotes] = useState("");
  const [bookingOpen, setBookingOpen] = useState(false);
  const [bookingSuccess, setBookingSuccess] = useState(false);
  const [confirmation, setConfirmation] = useState(null);

  const handleBook = () => setBookingOpen(true);
  const handleBookingConfirm = () => {
    setBookingOpen(false);
    setBookingSuccess(true);
    setConfirmation({
      date: selectedSlot,
      doctor,
      joinLink: consultType === "video" ? "https://video.consult/join/abc123" : null,
    });
    // Simulate sending email/SMS
    console.log("Email sent to patient with slot details");
  };

  return (
    <div className="max-w-3xl mx-auto p-6">
      {/* Doctor Info Section */}
      <Card className="mb-6">
        <CardContent className="flex flex-col sm:flex-row gap-6 items-center p-6">
          <Avatar className="w-24 h-24">
            <AvatarImage src={doctor.avatarUrl} alt={doctor.fullName} />
            <AvatarFallback>{doctor.fullName[0]}</AvatarFallback>
          </Avatar>
          <div className="flex-1">
            <div className="text-2xl font-bold text-gray-800">{doctor.fullName}</div>
            <Badge className="mt-1 mb-2">{doctor.specialization}</Badge>
            <div className="text-gray-600 text-sm mb-1">{doctor.address || (doctor.isOnline ? "Online Only" : "-")}</div>
            <div className="flex gap-4 text-xs text-gray-500 mb-1">
              <span>{doctor.experience} yrs exp</span>
              <span>⭐ {doctor.rating}</span>
              <span>{doctor.languages.join(", ")}</span>
            </div>
            <Button className="mt-2" onClick={handleBook}>Book Appointment</Button>
          </div>
        </CardContent>
      </Card>

      {/* Bio/About Section */}
      <Card className="mb-6">
        <CardContent className="p-6">
          <div className="font-semibold mb-2">About</div>
          <Textarea value={doctor.bio} readOnly className="resize-none bg-gray-50" />
        </CardContent>
      </Card>

      {/* Available Slots Section */}
      <Card className="mb-6">
        <CardContent className="p-6">
          <div className="font-semibold mb-2">Available Slots</div>
          <SlotPicker
            slots={doctor.slots}
            value={selectedSlot}
            onChange={setSelectedSlot}
          />
        </CardContent>
      </Card>

      {/* Consultation Mode & Booking Confirmation UI */}
      <Card className="mb-6">
        <CardContent className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <div className="font-semibold mb-2">Consultation Mode</div>
            <Select value={consultType} onValueChange={setConsultType}>
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Select mode" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="inperson">In-person</SelectItem>
                <SelectItem value="video">Video</SelectItem>
              </SelectContent>
            </Select>
            <div className="mt-4 font-semibold mb-2">Duration</div>
            <div className="flex gap-2">
              <Button variant={duration === "15" ? "default" : "outline"} onClick={() => setDuration("15")}>15 min</Button>
              <Button variant={duration === "30" ? "default" : "outline"} onClick={() => setDuration("30")}>30 min</Button>
            </div>
          </div>
          <div>
            <div className="font-semibold mb-2">Booking Details</div>
            <div className="mb-2 text-sm">Patient: <span className="font-medium">{mockPatient.name}</span></div>
            <Textarea
              placeholder="Notes for doctor (optional)"
              value={notes}
              onChange={e => setNotes(e.target.value)}
              className="mb-2"
            />
            <div className="mb-2 text-sm">Fee: <span className="font-medium">₹{doctor.fee}</span></div>
            <Button
              className="w-full"
              disabled={!selectedSlot}
              onClick={() => setBookingOpen(true)}
            >
              Confirm Booking
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Booking Confirmation Dialog */}
      <Dialog open={bookingOpen} onOpenChange={setBookingOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Appointment</DialogTitle>
          </DialogHeader>
          <div className="mb-2">Doctor: <span className="font-medium">{doctor.fullName}</span></div>
          <div className="mb-2">Slot: <span className="font-medium">{selectedSlot ? new Date(selectedSlot.datetime).toLocaleString() : "-"}</span></div>
          <div className="mb-2">Consultation: <span className="font-medium">{consultType === "video" ? "Video" : "In-person"}</span></div>
          <div className="mb-2">Duration: <span className="font-medium">{duration} min</span></div>
          <div className="mb-2">Fee: <span className="font-medium">₹{doctor.fee}</span></div>
          <div className="mb-2">Patient: <span className="font-medium">{mockPatient.name}</span></div>
          <div className="mb-2">Notes: <span className="font-medium">{notes || "-"}</span></div>
          <DialogFooter>
            <Button onClick={handleBookingConfirm}>Book Appointment</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Success Confirmation UI */}
      {bookingSuccess && (
        <Card className="mb-6 bg-green-50 border-green-300">
          <CardContent className="p-6 text-center">
            <div className="text-lg font-bold text-green-700 mb-2">Appointment Confirmed!</div>
            <div className="mb-1">Doctor: <span className="font-medium">{doctor.fullName}</span></div>
            <div className="mb-1">Date: <span className="font-medium">{confirmation?.date ? new Date(confirmation.date.datetime).toLocaleString() : "-"}</span></div>
            {confirmation?.joinLink && (
              <div className="mb-1">Join Link: <a href={confirmation.joinLink} className="text-blue-600 underline" target="_blank" rel="noopener noreferrer">Join Video Call</a></div>
            )}
            <div className="mt-2 text-sm text-gray-500">A confirmation email has been sent to you.</div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
